
const modes={car:{target:'https://a3tal.com/',name:'s',placeholder:'ابحث باسم السيارة أو الموديل'},code:{target:'https://a3tal.com/dtc/',name:'code',placeholder:'مثال: P0420'},compare:{target:'https://a3tal.com/',name:'s',placeholder:'ابحث عن مقارنة بين سيارتين'},spec:{target:'https://a3tal.com/car-reference/',name:'q',placeholder:'ابحث عن مواصفات الموديل'}};document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-mode]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const m=modes[b.dataset.mode],f=document.getElementById('searchForm'),i=document.getElementById('query');f.action=m.target;i.name=m.name;i.placeholder=m.placeholder;i.value='';i.focus();}));document.getElementById('menuToggle')?.addEventListener('click',(e)=>{const nav=document.querySelector('.a3r-site-header .desktop-nav');const open=nav.classList.toggle('is-open');e.currentTarget.setAttribute('aria-expanded',String(open));});
